import{_ as i,o as a,c as s,a3 as t}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"从源码构建","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"从源码构建 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/dev/build"}]]},"headers":[],"relativePath":"zh/clice/dev/build.md","filePath":"zh/clice/dev/build.md","lastUpdated":1791190778000}'),l={name:"zh/clice/dev/build.md"};function n(c,e,p,o,d,r){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h1><p>clice 依赖 C++23 特性，需要使用现代 C++ 工具链。同时还需要链接 LLVM/Clang 以解析 AST。两者都来自 clice-io 的 clang 工具链 <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a>：<a href="https://bazel.build" target="_blank" rel="noreferrer">Bazel</a> 使用 xclang 的工具链构建 clice，并链接同一 xclang 版本预编译的 LLVM/Clang 库，工具链和库都由 Bazel 自行下载。二者必须匹配：这些库里是 ThinLTO bitcode，只有该版本的工具链能读取。</p><p>为了简化环境配置并确保构建可复现，我们<strong>强烈推荐</strong>使用 <a href="https://pixi.prefix.dev/latest" target="_blank" rel="noreferrer">pixi</a> 管理开发环境。依赖版本固定在 <code>pixi.toml</code> 中；Bazel 的依赖版本固定在 <code>MODULE.bazel</code> 中。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>请按照<a href="https://pixi.prefix.dev/latest/installation" target="_blank" rel="noreferrer">官方指南</a>安装 pixi。</p><p>我们提供了多项任务；以下命令会构建并运行测试：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># build (default RelWithDebInfo) into build/RelWithDebInfo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># unit + integration + smoke + snap tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>如需使用粒度更细的任务（第一个参数用于指定构建类型）：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unit-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integration-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> smoke-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> snap-test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Debug</span></span></code></pre></div><p><code>pixi run build</code> 用 Bazel 构建 <code>//:dist</code>。每种构建类型都有自己的目录 <code>build/&lt;type&gt;</code>，其中的 <code>bin</code> 就是 Bazel 为该类型生成的输出树：clice 位于 <code>build/&lt;type&gt;/bin/bin/clice</code>，与之并列的是资源目录 <code>build/&lt;type&gt;/bin/lib/clang</code>，clice 从中读取 clang 的头文件；测试和编辑器都从这里运行它。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>运行 <code>pixi shell</code> 可进入已配置好所有环境变量的 shell，在其中用 <code>npx bazel</code> 直接调用 Bazel。</p></div><h2 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h2><p>Bazel 通过 <a href="https://github.com/bazelbuild/bazelisk" target="_blank" rel="noreferrer">bazelisk</a> 运行。bazelisk 是仓库中的一个 npm 包（由 <code>npm install</code> 安装），它会下载 <code>.bazelversion</code> 指定的 Bazel 版本：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bazel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/clice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> //:bin/unit_tests</span></span></code></pre></div><p>构建类型即 <code>.bazelrc</code> 中定义的配置：</p><table tabindex="0"><thead><tr><th>配置</th><th>作用</th></tr></thead><tbody><tr><td><code>--config=RelWithDebInfo</code></td><td>默认配置：开启优化，带调试信息</td></tr><tr><td><code>--config=Debug</code></td><td>不开启优化，启用 Address Sanitizer；Windows 上不启用</td></tr></tbody></table><p><code>--</code> 之后的选项会经由 <code>pixi run build</code> 传给 Bazel，例如 <code>pixi run build RelWithDebInfo -- //:package</code>。</p><p>LLVM/Clang 库是 ThinLTO bitcode，每次链接程序都要重做它们的代码生成，每个程序要花几分钟。lld 会把生成的结果存进缓存 <code>/var/tmp/xclang-thinlto</code>（Windows 上是 <code>C:/xclang-thinlto</code>），之后的链接只需几秒。</p><p><code>npx bazel build //:package //:symbols</code> 会构建发布归档和符号包（即未 strip 的 clice）：<code>build/&lt;type&gt;/bin</code> 中的 <code>clice.tar.gz</code> 和 <code>clice-symbol.tar.xz</code>（Windows 上为 <code>.zip</code>）。</p><p><code>npx bazel run //:compile_commands</code> 会在仓库根目录写出 clice 自身源码的 <code>compile_commands.json</code>，这样 clice 也能用于开发它自己的代码；它运行的是 <a href="https://github.com/kiron1/bazel-compile-commands" target="_blank" rel="noreferrer">bazel-compile-commands</a>。</p><p>在 Windows 上，Bazel 默认的输出根目录层级过深，超出了 Windows 路径的限制；请在 <code>%USERPROFILE%\\.bazelrc</code> 中指定一个较短的路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startup --output_user_root=C:/b</span></span></code></pre></div><p>在 Windows 上，Bazel 还需要 Bash，可由 <a href="https://gitforwindows.org" target="_blank" rel="noreferrer">Git for Windows</a> 提供。</p><h2 id="关于-llvm" tabindex="-1">关于 LLVM <a class="header-anchor" href="#关于-llvm" aria-label="Permalink to &quot;关于 LLVM&quot;">​</a></h2><p>clice 调用 Clang API 解析 C++ 代码，因此必须链接 LLVM/Clang。由于 clice 使用 Clang 的私有头文件（发行版软件包通常不包含这些文件），因此无法直接使用系统提供的 LLVM 软件包。</p><p>每个 <a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">xclang</a> 版本都会为全部六个目标发布预编译的 LLVM/Clang 库（<code>libclang-*</code> 压缩包），由该版本自己的工具链构建；xclang 的 Bazel 模块把这些库声明为仓库（repository），Bazel 会连同工具链一起下载它们。</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>调试构建会启用 Address Sanitizer，并链接 xclang 为 x86_64 Linux 和 arm64 macOS 发布的 ASan 插桩库；arm64 Linux 和 x86_64 macOS 没有这类库，也没有调试构建。Windows 的调试构建链接发布版的库，不启用 Address Sanitizer。</p></div><p>自行构建的 LLVM/Clang 可通过 <code>--repo_env=XCLANG_LIBCLANG_ROOT=&lt;directory&gt;</code> 替换发布版的库（ASan 版本用 <code>XCLANG_LIBCLANG_ASAN_ROOT</code>）；它必须按 xclang 的方式构建，即使用 xclang 的 <code>scripts/toolchain.ts</code>；参见 <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a>。</p>`,28)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
